<?php
require_once __DIR__.'/../config/auth.php';require_role('kasir');$pdo=db();$id=(int)($_GET['id']??$_POST['id']??0);
function recalcOrder(PDO $pdo,int $id):void{$s=$pdo->prepare('SELECT COALESCE(SUM(subtotal),0),COALESCE(SUM((price-purchase_price)*quantity),0) FROM transaction_details WHERE transaction_id=?');$s->execute([$id]);[$sub,$profit]=$s->fetch(PDO::FETCH_NUM);$s=$pdo->prepare('SELECT discount FROM transactions WHERE id=?');$s->execute([$id]);$discount=min((float)$sub,(float)$s->fetchColumn());$pdo->prepare('UPDATE transactions SET subtotal=?,discount=?,total=?,profit=? WHERE id=?')->execute([$sub,$discount,$sub-$discount,$profit-$discount,$id]);}
$s=$pdo->prepare("SELECT * FROM transactions WHERE id=? AND branch_id=? AND status='open'");$s->execute([$id,branch_id()]);$order=$s->fetch();if(!$order){http_response_code(404);exit('Pesanan aktif tidak ditemukan.');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->beginTransaction();try{if(isset($_POST['identity'])){$pdo->prepare("UPDATE transactions SET order_name=?,table_number=? WHERE id=? AND branch_id=? AND status='open'")->execute([trim($_POST['order_name']),trim($_POST['table_number']),$id,branch_id()]);audit_log('order_identity_updated','transaction',$id,[],['name'=>$_POST['order_name'],'table'=>$_POST['table_number']]);}elseif(isset($_POST['add'])){$pid=(int)$_POST['product_id'];$qty=max(1,(int)$_POST['quantity']);$p=$pdo->prepare('SELECT * FROM products WHERE id=? AND branch_id=? AND is_active=1 FOR UPDATE');$p->execute([$pid,branch_id()]);$product=$p->fetch();if(!$product||$product['stock']<$qty)throw new RuntimeException('Stok produk tidak mencukupi.');$line=$product['selling_price']*$qty;$pdo->prepare('INSERT INTO transaction_details(transaction_id,product_id,product_name,price,purchase_price,quantity,subtotal) VALUES(?,?,?,?,?,?,?)')->execute([$id,$pid,$product['name'],$product['selling_price'],$product['purchase_price'],$qty,$line]);$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?')->execute([$qty,$pid]);recalcOrder($pdo,$id);audit_log('order_item_added','transaction',$id,[],['product'=>$product['name'],'qty'=>$qty]);}elseif(isset($_POST['update_item'])){$did=(int)$_POST['detail_id'];$qty=max(0,(int)$_POST['quantity']);$s=$pdo->prepare('SELECT d.* FROM transaction_details d JOIN transactions t ON t.id=d.transaction_id WHERE d.id=? AND t.id=? AND t.branch_id=? AND t.status="open" FOR UPDATE');$s->execute([$did,$id,branch_id()]);$d=$s->fetch();if(!$d)throw new RuntimeException('Item tidak ditemukan.');$delta=$qty-(int)$d['quantity'];$p=$pdo->prepare('SELECT stock FROM products WHERE id=? FOR UPDATE');$p->execute([$d['product_id']]);if($delta>0&&(int)$p->fetchColumn()<$delta)throw new RuntimeException('Stok tidak mencukupi.');$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?')->execute([$delta,$d['product_id']]);if($qty===0)$pdo->prepare('DELETE FROM transaction_details WHERE id=?')->execute([$did]);else $pdo->prepare('UPDATE transaction_details SET quantity=?,subtotal=price*? WHERE id=?')->execute([$qty,$qty,$did]);recalcOrder($pdo,$id);audit_log('order_item_updated','transaction',$id,['qty'=>$d['quantity']],['qty'=>$qty]);}$pdo->commit();flash('success','Pesanan berhasil diperbarui.');}catch(Throwable $e){$pdo->rollBack();flash('error',$e->getMessage());}redirect('/kasir/order_edit.php?id='.$id);}
$s=$pdo->prepare('SELECT * FROM transaction_details WHERE transaction_id=? ORDER BY id');$s->execute([$id]);$items=$s->fetchAll();$s=$pdo->prepare('SELECT id,name,stock FROM products WHERE branch_id=? AND is_active=1 AND stock>0 ORDER BY name');$s->execute([branch_id()]);$products=$s->fetchAll();$pageTitle='Edit Pesanan';$active='pesanan';include __DIR__.'/../includes/header.php';?>
<div class="grid two-col"><section class="card"><h2>Identitas pesanan</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$id?>"><label>Nama<input name="order_name" value="<?=e($order['order_name'])?>"></label><label>Meja<input name="table_number" value="<?=e($order['table_number'])?>"></label><button class="btn primary" name="identity">Simpan identitas</button></form><h2 style="margin-top:24px">Tambah menu</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$id?>"><label class="field full">Produk<select name="product_id"><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?> · stok <?=$p['stock']?></option><?php endforeach;?></select></label><label>Jumlah<input type="number" name="quantity" min="1" value="1"></label><button class="btn primary" name="add">Tambah</button></form></section><section class="card"><h2>Daftar item</h2><?php foreach($items as $i):?><form method="post" class="summary-row"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="detail_id" value="<?=$i['id']?>"><span><strong><?=e($i['product_name'])?></strong><br><small><?=rupiah($i['price'])?></small></span><input type="number" name="quantity" min="0" value="<?=$i['quantity']?>" style="width:80px"><button class="btn soft sm" name="update_item">Ubah</button></form><?php endforeach;?><div class="summary-row total"><span>Total</span><strong><?=rupiah($order['total'])?></strong></div><a class="btn primary wide" href="pesanan.php">Kembali ke Pesanan Aktif</a></section></div><?php include __DIR__.'/../includes/footer.php';?>
